% Routing entropy figure moved to main text (Figure 2)

\section{Experimental Setup Details}
\label{app:setup}

\paragraph{Backbone specifications.} MOMENT-small ($d{=}512$, 8 encoder blocks, internal RevIN); MOMENT-large ($d{=}1024$, 24 blocks, internal RevIN); Moirai ($d{=}384$, 6 blocks, LayerNorm only); Moirai-MoE ($d{=}384$, 6 blocks, LayerNorm only with sparse internal experts); Chronos ($d{=}512$, 6 encoder blocks, no instance normalization); Timer-XL ($d{=}1024$, 8 blocks, no instance normalization). Throughout, ``full fine-tuning'' means \emph{all} encoder blocks are unfrozen (8/8 for MOMENT-small, 24/24 for MOMENT-large, 6/6 for Moirai/Moirai-MoE/Chronos, 8/8 for Timer-XL).

\paragraph{Training hyperparameters.} Adam optimizer, learning rate $10^{-3}$, MSE loss, batch size $128$, $15$ epochs. Final reported numbers are 15-epoch test MSE. Core multi-seed grids use seeds $\{42, 43, 44, 45, 46\}$ ($n{=}5$); ablations use seeds $\{42, 43, 44\}$ ($n{=}3$). Channel-wise StandardScaler normalization~\citep{zhou2021informer, nie2023patchtst} is applied to all inputs.

\paragraph{Per-baseline configurations.}
\begin{itemize}[leftmargin=1.2em, itemsep=0.15em, topsep=0.2em]
\item \textbf{Fixed adapters}: linear, attention-pool, Conv1d-pool single-head topologies with $\leq 500{,}000$ trainable parameters.
\item \textbf{LoRA}~\citep{hu2022lora}: 108-run sweep (12 configurations $\times$ 3 seeds $\times$ 3 datasets) over rank, target projections, and forecast head; full table in Appendix~\ref{app:lora_sweep}.
\item \textbf{TRACE}~\citep{li2025trace}: importance-based LoRA selection with default settings.
\item \textbf{Independent ensemble}: 5 experts with the canonical pool topologies, trained independently with no router and averaged at inference.
\item \textbf{AdaMix}~\citep{wang2022adamix}: $K{=}5$ canonical heads with hidden-state softmax router; load-balance coefficient $0.01$. Full implementation details in Appendix~\ref{app:adamix_details}.
\item \textbf{Full fine-tuning}: all encoder blocks unfrozen; best of $5$ head topologies $\times$ $2$ learning rates ($10^{-4}$, $10^{-5}$). Extended sweeps in Appendix~\ref{app:extended_ft}.
\item \textbf{DLinear}~\citep{zeng2023dlinear}: from-scratch supervised; we use the simplified single-Linear variant ($\text{Linear}(L{=}512 \to H{=}96)$, $49$K params), without the trend-seasonal decomposition, as the calibration anchor. Calibration values $0.416 / 0.322 / 0.208$ on ETTh1/ETTm1/Weather (gap to RR-MoA visible in Tables~\ref{tab:rrmoa},~\ref{tab:baselines}).
\end{itemize}

\paragraph{RR-MoA pseudocode.}
\begin{algorithm}[h]
\caption{RR-MoA: Raw-Routed Mixture of Adapters with Top-$k$ sparse routing}
\label{alg:rrmoa}
\begin{algorithmic}[1]
\REQUIRE Strictly frozen TSFM $f_{\theta_\text{frozen}}$, raw input $\mathbf{X}_\text{raw}\in\mathbb{R}^{B\times L}$, $K$ expert adapters, sparsity $k\leq K$
\STATE $\mathbf{H}\leftarrow f_{\theta_\text{frozen}}(\mathbf{X}_\text{raw})$ \hfill \COMMENT{Deep embeddings; \textbf{no gradients} through $\theta$}
\STATE $\mathbf{g}\leftarrow G_\psi(\mathbf{X}_\text{raw})$ \hfill \COMMENT{Raw-signal gate logits, $\mathbf{g}\in\mathbb{R}^{B\times K}$}
\STATE $\mathcal{T}\leftarrow \mathrm{TopK}(\mathbf{g},\,k)$ \hfill \COMMENT{Per-sample indices of the $k$ selected experts}
\STATE $\widetilde{\mathbf{w}}\leftarrow \mathrm{softmax}_{\mathcal{T}}(\mathbf{g})$ \hfill \COMMENT{Renormalized over selected experts only}
\STATE \textbf{for each}\ $j \in \mathcal{T}$\ \textbf{do}
\STATE \quad $\mathbf{o}_j\leftarrow \text{Expert}_j(\mathbf{H})$ \hfill \COMMENT{Only the $k$ selected experts execute}
\STATE \textbf{end for}
\STATE $\mathbf{Y}\leftarrow \sum_{j\in\mathcal{T}}\widetilde{w}_j\cdot \mathbf{o}_j$
\RETURN $\mathbf{Y}$
\end{algorithmic}
\end{algorithm}

\section{Deployment-Regime Motivation}
\label{app:deployment}

The frozen-backbone paradigm is motivated by three deployment regimes where full fine-tuning is infeasible:

\textbf{(i) Multi-tenant cloud serving.} A single TSFM sits in GPU memory and serves many tenants via lightweight, hot-swappable per-tenant adapters in host RAM. Per-tenant DLinear requires collecting, storing, and periodically retraining on each tenant's historical data ($O(N)$ training pipelines for $N$ tenants), whereas the frozen backbone is loaded once and adapter weights are swapped from host RAM. The adapter approach also enables instant onboarding of new tenants via zero-shot transfer, a capability absent from per-tenant supervised baselines.

\textbf{(ii) On-device and edge deployment.} One backbone is shipped with the device image; per-site adapters are updated over low-bandwidth links. Collecting each site's training data centrally is often impossible for privacy or latency reasons.

\textbf{(iii) Cross-task reuse.} The same frozen backbone drives forecasting, imputation, and classification via different expert pools. We demonstrate the first two tasks explicitly in the main text.

\subsection{Inference Benchmark}
\label{app:benchmark}

\begin{table}[h]
\centering
\caption{\textbf{Inference latency and memory across all three architectural variants} (MOMENT-small, A10G GPU, batch size $128$, $200$ repeats with $20$-step CUDA-event warmup; synthetic random inputs at the standard LTSF batch shape, since latency for non-autoregressive deterministic forward passes is data-oblivious). All three architectural fixes (RR-MoA, SR-MoA, Residual-IA\textsuperscript{+}) add only single-digit milliseconds of adapter overhead on top of the backbone forward pass; the frozen-backbone fast-inference property is preserved by each.}
\label{tab:benchmark}
\small
\begin{tabular}{@{}lcccc@{}}
\toprule
Method & Latency (ms) & $\Delta$ vs.\ backbone & Peak GPU (MB) & Adapter params \\
\midrule
Backbone only                                & $52.89 \pm 0.36$ & ---            & $359$ & --- \\
Single adapter (Conv1dPool)                  & $53.57 \pm 0.37$ & $+1.3\%$       & $360$ & $268$K \\
\textbf{RR-MoA (Top-2, $K{=}5$)}             & $\mathbf{56.02 \pm 0.44}$ & $\mathbf{+5.9\%}$ & $\mathbf{362}$ & $\mathbf{426}$\textbf{K} \\
\textbf{SR-MoA (dense $K{=}5$)}              & $\mathbf{54.20 \pm 0.79}$ & $\mathbf{+2.5\%}$ & $\mathbf{364}$ & $\mathbf{466}$\textbf{K} \\
\textbf{Residual-IA\textsuperscript{+}}      & $\mathbf{54.53 \pm 0.43}$ & $\mathbf{+3.1\%}$ & $\mathbf{365}$ & $\mathbf{354}$\textbf{K} \\
\midrule
\rowcolor{gray!8} DLinear (no backbone)      & $0.04 \pm 0.00$ & ---            & $160$ & $49$K \\
\bottomrule
\end{tabular}
\end{table}

The RR-MoA routing overhead ($+3.1$\,ms) is dominated by the sparse expert selection loop; the router itself (Conv1d + linear, ${\sim}1.1$K params) adds $<0.1$\,ms. SR-MoA dense and Residual-IA\textsuperscript{+} both run \emph{faster} than RR-MoA Top-2 on GPU because their dense per-expert execution parallelizes over the $K{=}5$ expert dimension without per-sample sparse-routing kernel launches. Notably, Residual-IA\textsuperscript{+} has \emph{fewer} adapter parameters than RR-MoA ($354$K vs $426$K) thanks to the shared NLinear raw branch.

\textbf{What DLinear wins.} Per call, DLinear is ${\sim}1400\times$ faster ($0.04$ vs $56$\,ms) and uses ${\sim}2\times$ less peak GPU memory; for $N$ independent tasks served in isolation, $N$ DLinears are also smaller in aggregate than one TSFM plus $N$ adapters. We do not claim otherwise.

\textbf{What our adapters deliver in practice.} The numbers above quantify the cost of accessing a regime DLinear cannot serve at all. (i) \emph{Adapter overhead is bounded.} All three of our architectures stay within $+5.9\%$ of the raw backbone latency and add at most $6$\,MB of peak GPU memory (Table~\ref{tab:benchmark}); the frozen backbone is the cost floor, and the routing/expert machinery does not blow it up. (ii) \emph{Hot-swap, not retrain.} A new tenant or task is served by loading $354$--$466$\,K adapter parameters from host RAM into the resident backbone in sub-millisecond time; the per-tenant DLinear alternative requires collecting that tenant's history and running a fresh supervised training pipeline before the first prediction. (iii) \emph{One model, many tasks.} The same frozen backbone drives forecasting, imputation, and classification through different expert pools (\S\ref{sec:intro}, Appendix~\ref{app:imputation}); $N$ tasks consume one GPU residency rather than $N$. (iv) \emph{Zero-shot onboarding.} Adapter weights trained on related tenants transfer at load time, so a new deployment can serve predictions immediately rather than waiting for the data-collection-plus-training cycle that supervised per-task models require. The latency and memory numbers above are the price of these capabilities, not a claim of dominance over DLinear in DLinear's native single-task setting.

\section{Multi-Horizon Evaluation}
\label{app:horizon}

\begin{table}[h]
\centering
\caption{\textbf{Multi-horizon RR-MoA vs.\ DLinear} (MOMENT-small, strictly frozen, Top-2, 5 seeds, test MSE mean$\pm$std). RR-MoA wins all 24 configurations vs.\ best fixed baseline across horizons $96$--$720$. DLinear column provides supervised calibration: the gap narrows from $+63\%$ to $+48\%$ on ETTh1 and from $+33\%$ to $+15\%$ on Weather as $H$ grows, consistent with the frozen backbone's horizon-invariant representation becoming relatively more informative at longer horizons.}
\label{tab:horizon}
\scriptsize
\begin{tabular}{@{}lccccccccc@{}}
\toprule
 & \multicolumn{3}{c}{ETTh1} & \multicolumn{3}{c}{ETTm1} & \multicolumn{3}{c}{Weather} \\
\cmidrule(lr){2-4} \cmidrule(lr){5-7} \cmidrule(lr){8-10}
$H$ & RR-MoA & Best fix & DLin & RR-MoA & Best fix & DLin & RR-MoA & Best fix & DLin \\
\midrule
96  & $0.680{\pm}.030$ & $1.233$ & $\mathit{0.420}$ & $0.564{\pm}.066$ & $1.169$ & $\mathit{0.326}$ & $0.276{\pm}.019$ & $0.522$ & $\mathit{0.207}$ \\
192 & $0.773{\pm}.071$ & $1.326$ & $\mathit{0.476}$ & $0.632{\pm}.039$ & $1.141$ & $\mathit{0.365}$ & $0.292{\pm}.009$ & $0.498$ & $\mathit{0.246}$ \\

